// Solid only where Material's rounded glyph means "selected / on"; everything else uses the light outline.
private val Solid = setOf(
    "Home", "Search", "LibraryMusic", "Settings", "Favorite", "PlayArrow", "Pause", "SkipNext", "SkipPrevious",
    "FastForward", "FastRewind", "PlayCircle", "Bookmark", "ThumbDown", "DownloadDone", "AccountCircle",
)

private val fluentCache = HashMap<String, androidx.compose.ui.graphics.vector.ImageVector?>()

/** Fluent counterpart of a Material icon, or null to keep the original. */
fun fluentFor(v: androidx.compose.ui.graphics.vector.ImageVector): androidx.compose.ui.graphics.vector.ImageVector? = fluentCache.getOrPut(v.name) {
    val n = v.name.removePrefix("AutoMirrored.")
    val style = n.substringBefore('.')
    val simple = n.substringAfter('.')
    val (regular, filled) = FluentPaths[simple] ?: return@getOrPut null
    val solid = style != "Outlined" && simple in Solid
    androidx.compose.ui.graphics.vector.ImageVector.Builder("Fluent.$n", 24.dp, 24.dp, 24f, 24f, autoMirror = v.autoMirror)
        .addPath(androidx.compose.ui.graphics.vector.addPathNodes(if (solid) filled else regular), fill = androidx.compose.ui.graphics.SolidColor(androidx.compose.ui.graphics.Color.Black))
        .build()
}
